public str process(str _imageId)
{
    str				ret;
    SysDictClass	DC;

    if (SysTest::hasMethod(this,_imageId))
    {
        DC = new SysDictClass(classIdGet(this));

        return DC.callObject(_imageId,this);
    }

    return ret;
}

	public str workLog()
    {
        str						base64;

        base64 = TFMImageCombiner::combineImage(base64,resourceStr(TFMPickIcon),50,50,100,100,false);
        base64 = TFMImageCombiner::combineImage(base64,resourceStr(TFMStopWatch),80,75,40,40,true);

        return base64;
    }
